import React from 'react';
import { Navigate } from 'react-router-dom';
import { useApp } from '../context/AppContext';
import { CheckSquare, Plus, Calendar, Clock, AlertCircle, Edit2, Trash2 } from 'lucide-react';

const Tasks: React.FC = () => {
  const { user } = useApp();

  if (!user) {
    return <Navigate to="/login" replace />;
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold text-gray-900 dark:text-white">
            Task Manager
          </h1>
          <p className="text-gray-600 dark:text-gray-300 mt-2">
            Manage your daily tasks and stay organized
          </p>
        </div>
        <button className="btn-primary">
          <Plus className="w-4 h-4 mr-2" />
          Add Task
        </button>
      </div>

      <div className="card p-8 text-center">
        <CheckSquare className="w-16 h-16 text-gray-400 mx-auto mb-4" />
        <h3 className="text-lg font-medium text-gray-900 dark:text-white mb-2">
          Task Manager Coming Soon
        </h3>
        <p className="text-gray-600 dark:text-gray-300">
          This feature is currently being developed. You'll be able to add, edit, and manage your tasks here.
        </p>
      </div>
    </div>
  );
};

export default Tasks;
